sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float progress;
uniform float start;
uniform float2 center;
uniform float feather;
uniform float direction;
uniform float count;
half4 main(float2 coord) {
    float2 d = coord - center * size;
    float n = max(floor(count + 0.5), 1.0);
    float a = mod(degrees(atan(d.x, -d.y)) - start, 360.0);
    if (direction > 0.5 && direction < 1.5) a = 360.0 - a;
    a = mod(a, 360.0 / n) * n;
    float sweep = clamp(progress, 0.0, 360.0);
    if (direction > 1.5) {
        a = min(a, 360.0 - a) * 2.0;
    }
    float soft = max(feather, 0.0001);
    float hide = (1.0 - smoothstep(sweep - soft, sweep, a)) * step(0.0001, sweep);
    if (sweep >= 360.0) hide = 1.0;
    return image.eval(coord) * half(1.0 - hide);
}
